// 离线PCAP分析器：复刻 findCandidates 逻辑，诊断解码失败层
import Foundation

let kMaxLocationAbs: Double = 2_000_000.0
let kMaxRotationAbs: Double = 180.001

func bits(_ data: [UInt8], offset: Int, count: Int) -> UInt64 {
    if count <= 0 || count > 63 || offset < 0 { return 0 }
    let firstByte = offset / 8
    let lastByte = (offset + count + 7) / 8
    if firstByte < 0 || lastByte > data.count || lastByte <= firstByte { return 0 }
    var value: UInt64 = 0
    for i in stride(from: lastByte - 1, through: firstByte, by: -1) {
        value = (value << 8) | UInt64(data[i])
    }
    return (value >> UInt64(offset % 8)) & ((UInt64(1) << UInt64(count)) - 1)
}

func ue5Vector(_ data: [UInt8], offset: Int, scale: Int) -> ((Double,Double,Double), Int, Int, Bool)? {
    let header = bits(data, offset: offset, count: 7)
    var cursor = offset + 7
    let width = Int(header & 63)
    let isScaled = (header >> 6) & 1 != 0
    if width == 0 { return nil }
    let sign = UInt64(1) << (width - 1)
    let modulus = UInt64(1) << width
    var values: [Double] = []
    for _ in 0..<3 {
        var v = bits(data, offset: cursor, count: width)
        cursor += width
        if v & sign != 0 { v = v &- modulus }
        values.append(isScaled ? Double(v) / Double(scale) : Double(v))
    }
    return ((values[0], values[1], values[2]), cursor, width, isScaled)
}

func ue5Rotator(_ data: [UInt8], offset: Int) -> ((Double,Double,Double), Int)? {
    var values: [Double] = []
    var cursor = offset
    for _ in 0..<3 {
        let present = bits(data, offset: cursor, count: 1)
        cursor += 1
        var angle: Double = 0
        if present != 0 {
            let compressed = bits(data, offset: cursor, count: 16)
            cursor += 16
            angle = Double(compressed) * 360.0 / 65536.0
            if angle > 180.0 { angle -= 360.0 }
        }
        values.append(angle)
    }
    return ((values[0], values[1], values[2]), cursor)
}

func hasValidRotation(_ data: [UInt8], offset: Int) -> Bool {
    var flags: [Bool] = []
    var cursor = offset
    for _ in 0..<3 {
        let present = bits(data, offset: cursor, count: 1) != 0
        flags.append(present)
        cursor += 1 + (present ? 16 : 0)
    }
    guard let (rot, end) = ue5Rotator(data, offset: offset) else { return false }
    if end > data.count * 8 { return false }
    return flags[1] && !flags[2]
        && abs(rot.0) <= 90.001
        && abs(rot.0) <= kMaxRotationAbs
        && abs(rot.1) <= kMaxRotationAbs
        && abs(rot.2) <= kMaxRotationAbs
}

/// 复刻 findCandidates，返回候选列表 + 各阶段淘汰统计
func analyze(_ payload: [UInt8]) -> (cands: [(Int, Double, Double, Double, Double)], failTime: Int, failAccel: Int, failLoc: Int, failRot: Int) {
    var cands: [(Int, Double, Double, Double, Double)] = []
    var failTime = 0, failAccel = 0, failLoc = 0, failRot = 0
    let searchEnd = min(512, payload.count * 8 - 60)
    guard searchEnd > 190 else { return (cands, failTime, failAccel, failLoc, failRot) }
    for offset in 190..<searchEnd {
        let timeBits = bits(payload, offset: offset, count: 32)
        let clientTime = Float(bitPattern: UInt32(timeBits))
        if !clientTime.isFinite || clientTime < 0 || clientTime >= 100_000 { failTime += 1; continue }
        guard let (accel, cursor, accelBits, accelScaled) = ue5Vector(payload, offset: offset + 32, scale: 10) else { failAccel += 1; continue }
        if !accelScaled { failAccel += 1; continue }
        if accelBits < 1 || accelBits > 16 { failAccel += 1; continue }
        if max(abs(accel.0), max(abs(accel.1), abs(accel.2))) >= 50_000 { failAccel += 1; continue }
        guard let (loc, locEnd, locBits, locScaled) = ue5Vector(payload, offset: cursor, scale: 100) else { failLoc += 1; continue }
        if !locScaled { failLoc += 1; continue }
        if locBits < 20 || locBits > 32 { failLoc += 1; continue }
        if max(abs(loc.0), max(abs(loc.1), abs(loc.2))) > kMaxLocationAbs { failLoc += 1; continue }
        let rotationOffset = locEnd + 7
        if !hasValidRotation(payload, offset: rotationOffset) { failRot += 1; continue }
        cands.append((offset, Double(clientTime), accel.0, loc.0, loc.1))
    }
    return (cands, failTime, failAccel, failLoc, failRot)
}

