// diffstool.swift — 按方向+长度分组 30120 payload，逐字节统计变化度（stand vs walk）
// 用法: swift diffstool.swift <pcap1> [pcap2 ...]
import Foundation

func readPCAP(_ path: String) -> [(time: Double, data: [UInt8])] {
    guard let raw = try? Data(contentsOf: URL(fileURLWithPath: path)) else { return [] }
    let bytes = [UInt8](raw)
    var pkts: [(Double, [UInt8])] = []
    guard bytes.count > 24 else { return [] }
    var off = 24
    while off + 16 <= bytes.count {
        func u32(_ o: Int) -> UInt32 { UInt32(bytes[o]) | UInt32(bytes[o+1])<<8 | UInt32(bytes[o+2])<<16 | UInt32(bytes[o+3])<<24 }
        let ts = Double(u32(off)) + Double(u32(off+4)) / 1_000_000.0
        let incl = Int(u32(off+8)), orig = Int(u32(off+12))
        guard incl >= 0, off + 16 + incl <= bytes.count, orig > 0, incl > 0 else { break }
        let frame = Array(bytes[off+16 ..< off+16+incl])
        pkts.append((ts, frame))
        off += 16 + incl
    }
    return pkts.map { ($0.0, $0.1) }
}

// Ethernet14 + IP20 + UDP8 = 42；UDP payload
func udpPayload(_ frame: [UInt8]) -> (src: String, dst: String, sport: UInt16, dport: UInt16, payload: [UInt8])? {
    guard frame.count >= 42 else { return nil }
    let et = (UInt16(frame[12]) << 8) | UInt16(frame[13])
    var ipOff = 14
    if et == 0x8100 { guard frame.count >= 46 else { return nil }; ipOff = 18 } // VLAN
    guard et == 0x0800 || et == 0x8100 else { return nil }
    let ihl = Int(frame[ipOff] & 0x0F) * 4
    guard frame.count >= ipOff + ihl + 8 else { return nil }
    let proto = frame[ipOff + 9]
    guard proto == 17 else { return nil }
    let sport = (UInt16(frame[ipOff+ihl]) << 8) | UInt16(frame[ipOff+ihl+1])
    let dport = (UInt16(frame[ipOff+ihl+2]) << 8) | UInt16(frame[ipOff+ihl+3])
    let ulen = Int(frame[ipOff+ihl+4]) << 8 | Int(frame[ipOff+ihl+5])
    let payLen = max(0, ulen - 8)
    guard payLen > 0, frame.count >= ipOff + ihl + 8 + payLen else { return nil }
    func ip(_ o: Int) -> String { "\(frame[o]).\(frame[o+1]).\(frame[o+2]).\(frame[o+3])" }
    return (ip(ipOff+12), ip(ipOff+16), sport, dport, Array(frame[ipOff+ihl+8 ..< ipOff+ihl+8+payLen]))
}

var groups: [String: [[UInt8]]] = [:]
for path in CommandLine.arguments.dropFirst() {
    for (_, f) in readPCAP(path) {
        if let u = udpPayload(f), u.dport == 30120 || u.sport == 30120 {
            let dir = u.dport == 30120 ? "S2C" : "C2S"
            let key = "\(dir)/len=\(u.payload.count)"
            groups[key, default: []].append(u.payload)
        }
    }
}

print("=== 分组统计（值空间熵：distinct=不同字节数, spread=(max-min)）===")
for key in groups.keys.sorted(by: { groups[$0]!.count > groups[$1]!.count }) {
    let pkts = groups[key]!
    guard pkts.count >= 5 else { continue }
    let n = pkts[0].count
    var line = "\(key)  n=\(pkts.count)  per-byte: "
