import Foundation
func readPCAP(_ path: String) -> [(Double,[UInt8])] {
    guard let raw = try? Data(contentsOf: URL(fileURLWithPath: path)) else { return [] }
    let b = [UInt8](raw); var r: [(Double,[UInt8])] = []; var off = 24
    while off+16 <= b.count {
        func u32(_ o:Int)->UInt32{UInt32(b[o])|UInt32(b[o+1])<<8|UInt32(b[o+2])<<16|UInt32(b[o+3])<<24}
        let ts=Double(u32(off))+Double(u32(off+4))/1e6; let incl=Int(u32(off+8))
        guard incl>0, off+16+incl<=b.count else {break}
        r.append((ts,Array(b[off+16..<off+16+incl]))); off+=16+incl }
    return r }
func up(_ f:[UInt8])->[UInt8]?{
    guard f.count>=42,(UInt16(f[12])<<8)|UInt16(f[13])==0x0800 else{return nil}
    let ihl=Int(f[14]&0x0F)*4; guard f.count>=14+ihl+8,f[14+9]==17 else{return nil}
    let dp=(UInt16(f[14+ihl+2])<<8)|UInt16(f[14+ihl+3])
    let ul=Int(f[14+ihl+4])<<8|Int(f[14+ihl+5]); guard ul>=8, f.count>=14+ihl+ul else{return nil}
    return dp==30120 ? Array(f[14+ihl+8..<14+ihl+ul]) : nil }
