guard pkts.count > 10, let t0 = pkts.first?.0 else { print("样本不足"); exit(0) }
let wA = Double(a[2])!, wB = Double(a[3])!
let walk = pkts.filter { $0.0-t0 >= wA && $0.0-t0 < wB }
let still = pkts.filter { ($0.0-t0 < wA-2) || ($0.0-t0 >= wB+2) }
print("样本: 走相位 \(walk.count) 个, 静止 \(still.count) 个, 总 \(pkts.count)")
// 位读取
func bitAt(_ p:[UInt8], _ pos:Int)->Int { Int((p[pos/8] >> (7 - pos%8)) & 1) }
func bitsVal(_ p:[UInt8], _ pos:Int, _ n:Int)->Int64 {
    var v: Int64 = 0
    for i in 0..<n { v = (v << 1) | Int64(bitAt(p, pos+i)) }
    return v }
