            for p in walk { for k in 0..<3 { walkVals[k].append(bitsVal(p.1, startBit + k*strideBits, n)) } }
            // 走相位平滑性: 相邻 delta 与时间差的比值稳定度
            var scores: [Double] = []
            for k in 0..<3 {
                let v = walkVals[k]
                guard v.count >= 4 else { continue }
                var rates: [Double] = []
                var moved = 0
                for i in 1..<v.count {
                    let dt = walk[i].0 - walk[i-1].0
                    if dt < 0.15 || dt > 3.0 { continue }
                    let d = Double(v[i] - v[i-1])
                    if abs(d) > 1 { moved += 1 }
                    rates.append(abs(d)/dt) }
                // 变化明显 + 速率方差小
                if moved >= max(2, v.count/3), rates.count >= 3 {
                    let mean = rates.reduce(0,+)/Double(rates.count)
                    let varc = rates.map{($0-mean)*($0-mean)}.reduce(0,+)/Double(rates.count)
                    let cv = mean > 0 ? varc/mean : 9e9
                    scores.append(cv) } }
            if scores.count >= 2 {
                let avgCV = scores.reduce(0,+)/Double(scores.count)
                if avgCV < 25 {
                    print("★ bit@\(startBit) w=\(n) stride=\(strideBits) 静止distinct=\(stillDist) walkCV=\(String(format:"%.1f",avgCV))")
                    // 样例
                    var sample = ""
                    for i in 0..<min(6, walk.count) {
                        sample += String(format:"(%.1fs %d,%d,%d) ", walk[i].0-t0,
                            walkVals[0][i], walkVals[1][i], walkVals[2][i]) }
                    print("    \(sample)") } } } } }
