    if let pose = cc.read(maxAge: 1.0) {
        count += 1
        let now = Date()
        if now.timeIntervalSince(lastPrint) > 0.3 {
            lastPrint = now
            var delta = ""
            if let lp = lastPose {
                let dx = pose.0 - lp.0, dy = pose.1 - lp.1, dz = pose.2 - lp.2
                let d = (dx*dx+dy*dy+dz*dz).squareRoot()
                delta = String(format: " Δpos=%.1f", d)
            }
            lastPose = pose
            print(String(format: "[POS] #%d x=%.2f y=%.2f z=%.2f pitch=%.1f heading=%.1f%@", count, pose.0, pose.1, pose.2, pose.3, pose.4, delta))
        } else {
            lastPose = pose
        }
    } else {
        // 无数据：每 5 秒报一次
        let now = Date()
        if now.timeIntervalSince(lastPrint) > 5.0 {
            lastPrint = now
            print("[POS] (无数据) 累计解码=\(count)")
        }
    }
    usleep(100_000)  // 10Hz 轮询
}

