// stitch.swift — 把 MapSource z=0 的 51×51 张 512px 瓦片拼成 13056×13056 JPEG
// 用法: stitch <tilesDir> <output.jpg>
// 瓦片网格: tiles/0/{x}/{y}.jpg, x,y ∈ [0,50], 每张 512×512 = 2× 定位空间像素
// 定位空间 13056×13056, 每瓦片缩到 256×256. 瓦片 y=0 在顶部 (Web 约定),
// CGContext 原点在左下 → 目标 y = (50 - y_tile) * 256.
import CoreGraphics
import ImageIO
import Foundation
import UniformTypeIdentifiers

let args = CommandLine.arguments
guard args.count == 3 else { print("usage: stitch <tilesDir> <out.jpg>"); exit(1) }
let tilesDir = args[1], outPath = args[2]

let locatorSide = 13056
let tilesPerSide = 51
let tileSrc: CGFloat = 512
let tileDst: CGFloat = 256

let cs = CGColorSpace(name: CGColorSpace.sRGB)!
guard let ctx = CGContext(data: nil, width: locatorSide, height: locatorSide,
                          bitsPerComponent: 8, bytesPerRow: 0, space: cs,
                          bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else {
    print("FATAL: context alloc failed"); exit(2)
}
ctx.interpolationQuality = .high
ctx.setFillColor(CGColor(red: 0.05, green: 0.06, blue: 0.08, alpha: 1))
ctx.fill(CGRect(x: 0, y: 0, width: locatorSide, height: locatorSide))

var ok = 0, missing = 0
for tx in 0..<tilesPerSide {
    for ty in 0..<tilesPerSide {
        let p = "\(tilesDir)/\(tx)/\(ty).jpg"
        guard let src = CGImageSourceCreateWithURL(URL(fileURLWithPath: p) as CFURL, nil),
              let img = CGImageSourceCreateImageAtIndex(src, 0, nil) else {
            missing += 1
            continue
        }
        // y 翻转: 瓦片 y=0 → 画布顶部
        let rect = CGRect(x: CGFloat(tx) * tileDst,
                          y: CGFloat(tilesPerSide - 1 - ty) * tileDst,
                          width: tileDst, height: tileDst)
        ctx.draw(img, in: rect)
        ok += 1
    }
    if tx % 10 == 0 { FileHandle.standardError.write("row \(tx)/\(tilesPerSide)\n".data(using: .utf8)!) }
}
print("tiles ok=\(ok) missing=\(missing)")
guard let out = ctx.makeImage() else { print("FATAL: makeImage"); exit(3) }
let destURL = URL(fileURLWithPath: outPath) as CFURL
guard let dest = CGImageDestinationCreateWithURL(destURL, UTType.jpeg.identifier as CFString, 1, nil) else {
    print("FATAL: dest"); exit(4)
}
CGImageDestinationAddImage(dest, out, [kCGImageDestinationLossyCompressionQuality: 0.88] as CFDictionary)
guard CGImageDestinationFinalize(dest) else { print("FATAL: finalize"); exit(5) }
print("WROTE \(outPath) \(locatorSide)x\(locatorSide)")

