}

func udpPayload(_ frame: [UInt8]) -> (dir: String, payload: [UInt8])? {
    guard frame.count >= 42 else { return nil }
    let et = (UInt16(frame[12]) << 8) | UInt16(frame[13]); var ipOff = 14
    if et == 0x8100 { guard frame.count >= 46 else { return nil }; ipOff = 18 }
    guard et == 0x0800 else { return nil }
    let ihl = Int(frame[ipOff] & 0x0F) * 4
    guard frame.count >= ipOff + ihl + 8 else { return nil }
    guard frame[ipOff + 9] == 17 else { return nil }
    let sport = (UInt16(frame[ipOff+ihl]) << 8) | UInt16(frame[ipOff+ihl+1])
    let dport = (UInt16(frame[ipOff+ihl+2]) << 8) | UInt16(frame[ipOff+ihl+3])
    let ulen = Int(frame[ipOff+ihl+4]) << 8 | Int(frame[ipOff+ihl+5])
    let payLen = max(0, ulen - 8)
    guard payLen > 0, frame.count >= ipOff + ihl + 8 + payLen else { return nil }
    return (dport == 30120 ? "S2C" : "C2S", Array(frame[ipOff+ihl+8 ..< ipOff+ihl+8+payLen]))
}

