        if accelBits < 1 || accelBits > 16 { failAccel += 1; continue }
        if max(abs(accel.0), max(abs(accel.1), abs(accel.2))) >= 50_000 { failAccel += 1; continue }
        guard let (loc, locEnd, locBits, locScaled) = ue5Vector(payload, offset: cursor, scale: 100) else { failLoc += 1; continue }
        if !locScaled { failLoc += 1; continue }
        if locBits < 20 || locBits > 32 { failLoc += 1; continue }
        if max(abs(loc.0), max(abs(loc.1), abs(loc.2))) > kMaxLocationAbs { failLoc += 1; continue }
