let path = CommandLine.arguments.count > 1 ? CommandLine.arguments[1] : "/tmp/nte_test.pcap"
let f: FileHandle
do { f = try FileHandle(forReadingFrom: URL(fileURLWithPath: path)) } catch { fatalError("open fail: \(error)") }
var all = f.readDataToEndOfFile()
f.closeFile()
guard all.count > 24 else { fatalError("too small") }

// 全局头
let magicData = all.subdata(in: 0..<4)
let magicLE = magicData.withUnsafeBytes { $0.load(as: UInt32.self) }
let swap: Bool  // 需要字节交换
if magicLE == 0xa1b2c3d4 { swap = false }
else if magicLE == 0xd4c3b2a1 { swap = true }
else { fatalError("bad magic \(String(magicLE, radix: 16))") }
let linkType = all.subdata(in: 20..<24).withUnsafeBytes { raw -> UInt32 in
    let v = raw.load(as: UInt32.self)
    return swap ? v.byteSwapped : v
}
print("linkType=\(linkType) (1=Ethernet)")
if linkType != 1 { print("⚠️ 非以太网链路类型 linkType=\(linkType)") }

func u32(_ d: [UInt8], _ o: Int) -> UInt32 {
    var v: UInt32 = 0
    if swap { v = UInt32(d[o+3]) | UInt32(d[o+2]) << 8 | UInt32(d[o+1]) << 16 | UInt32(d[o]) << 24 }
    else { v = UInt32(d[o]) | UInt32(d[o+1]) << 8 | UInt32(d[o+2]) << 16 | UInt32(d[o+3]) << 24 }
    return v
}

var pos = 24
var nC2S = 0, nS2C = 0, nOther = 0
var c2sCandPkts = 0, s2cCandPkts = 0
var samplesShown = 0
var failAgg = (time: 0, accel: 0, loc: 0, rot: 0)

while pos + 16 <= all.count {
    let caplen = Int(u32([UInt8](all.subdata(in: pos+8..<pos+16)), 0))
    pos += 16
    guard pos + caplen <= all.count, caplen > 0 else { break }
    let pkt = [UInt8](all.subdata(in: pos..<pos+caplen))
    pos += caplen
    guard caplen > 34 else { continue }
    var o = 14
    let ipVer = (pkt[o] >> 4) & 0x0F
    guard ipVer == 4 else { continue }
    let ihl = Int(pkt[o] & 0x0F) * 4
    let proto = pkt[o + 9]
    let srcIP = "\(pkt[o+12]).\(pkt[o+13]).\(pkt[o+14]).\(pkt[o+15])"
    let dstIP = "\(pkt[o+16]).\(pkt[o+17]).\(pkt[o+18]).\(pkt[o+19])"
    o += ihl
    if proto == 6 {
        guard o + 20 <= caplen else { continue }
        o += Int(pkt[o+12] >> 4) * 4
    } else if proto == 17 { o += 8 }
    else { continue }
    guard o < caplen else { continue }
    let payload = Array(pkt[o...])
    let isC2S = srcIP == "192.168.1.3"
    let dir = isC2S ? "c2s" : (dstIP == "192.168.1.3" ? "s2c" : "?")
    if dir == "?" { nOther += 1; continue }
    if isC2S { nC2S += 1 } else { nS2C += 1 }
    guard payload.count >= 32 else { continue }
    let r = analyze(payload, verbose: true)
    failAgg.time += r.failTime; failAgg.accel += r.failAccel; failAgg.loc += r.failLoc; failAgg.rot += r.failRot
    if !r.cands.isEmpty {
        if isC2S { c2sCandPkts += 1 } else { s2cCandPkts += 1 }
        if samplesShown < 6 {
            samplesShown += 1
            let c = r.cands[0]
            print("★ \(dir) payload=\(payload.count)B 候选数=\(r.cands.count) offset=\(c.0) time=\(String(format: "%.2f", c.1)) accelX=\(String(format: "%.1f", c.2)) locX=\(String(format: "%.1f", c.3)) locY=\(String(format: "%.1f", c.4))")
        }
    }
}
print("═══ 汇总 ═══")
print("c2s=\(nC2S) s2c=\(nS2C) other=\(nOther)")
print("候选包: c2s=\(c2sCandPkts) s2c=\(s2cCandPkts)")
print("淘汰统计(全部偏移累计): 时间戳不合格=\(failAgg.time) 加速度不合格=\(failAgg.accel) 位置不合格=\(failAgg.loc) 旋转不合格=\(failAgg.rot)")
